WITH p AS (SELECT scorecard_id,max(scorecard_last_update_time) AS parent_version FROM scorecard_d WHERE scorecard_template_id='94e6b75d-b1eb-4e41-a477-1d070d96fa9c' AND scorecard_time >= '2026-07-01' AND scorecard_time < '2026-08-01' GROUP BY scorecard_id), s AS (SELECT DISTINCT scorecard_id,scorecard_last_update_time,criterion_id,percentage_value,float_weight FROM score_d WHERE scorecard_template_id='94e6b75d-b1eb-4e41-a477-1d070d96fa9c' AND scorecard_time >= '2026-07-01' AND scorecard_time < '2026-08-01' AND percentage_value>=0 AND NOT not_applicable) SELECT uniqExact(s.scorecard_id) AS matched_parents,sum(percentage_value*float_weight)/sum(float_weight) AS weighted_score FROM s INNER JOIN p ON s.scorecard_id=p.scorecard_id AND s.scorecard_last_update_time=p.parent_version FORMAT JSONEachRow;
